use super::*;

// ---------------------------------------------------
// We define some machinery here for enumerating the
// different cone types that can live in the composite cone
// ---------------------------------------------------

/// API type describing the type of a conic constraint.
///
#[derive(Debug, Clone, PartialEq)]
pub enum SupportedConeT {
    /// The zero cone (used for equality constraints).
    ///
    /// The parameter indicates the cones dimension.
    ZeroConeT(usize),
    /// The nonnegative orthant.  
    ///
    /// The parameter indicates the cones dimension.
    NonnegativeConeT(usize),
    /// The second order cone / Lorenz cone / ice-cream cone.
    ///  
    /// The parameter indicates the cones dimension.
    SecondOrderConeT(usize),
}

impl SupportedConeT {
    // this reports the number of slack variables that will be generated by
    // this cone.  Equivalent to `numels` for the internal cone representation.
    // Required for user data validation prior to building a problem.

    pub(crate) fn nvars(&self) -> usize {
        match self {
            SupportedConeT::ZeroConeT(dim) => *dim,
            SupportedConeT::NonnegativeConeT(dim) => *dim,
            SupportedConeT::SecondOrderConeT(dim) => *dim,
        }
    }
}

impl std::fmt::Display for SupportedConeT {
    fn fmt(&self, f: &mut std::fmt::Formatter) -> std::fmt::Result {
        write!(f, "{}", &self.as_tag().as_str())
    }
}

// we will use the SupportedConeT as a user facing marker
// for the constraint types, and then map them through
// make_cone to get the internal cone representations.

pub fn make_cone(cone: &SupportedConeT) -> SupportedCone {
    match cone {
        SupportedConeT::NonnegativeConeT(dim) => NonnegativeCone::new(*dim).into(),
        SupportedConeT::ZeroConeT(dim) => ZeroCone::new(*dim).into(),
        SupportedConeT::SecondOrderConeT(dim) => SecondOrderCone::new(*dim).into(),
    }
}

impl SupportedConeT {
    pub(crate) fn new_collapsed(cones: &[SupportedConeT]) -> Vec<SupportedConeT> {
        let mut newcones = Vec::with_capacity(cones.len());
        let mut iter = cones.iter().peekable();

        // rollup a subsequence of nonnegative cones or SOC/PSD singleton
        fn collapse(
            iter: &mut std::iter::Peekable<std::slice::Iter<'_, SupportedConeT>>,
            newcones: &mut Vec<SupportedConeT>,
            init_dim: usize,
        ) {
            let mut total_dim = init_dim;
            while let Some(next_cone) = iter.peek() {
                // skip empty cones
                if next_cone.nvars() != 0 {
                    match next_cone {
                        // collapsible cones.
                        SupportedConeT::NonnegativeConeT(dim) => total_dim += dim,
                        SupportedConeT::SecondOrderConeT(1) => total_dim += 1,

                        // stop when we hit a non-collapsible cone
                        _ => break,
                    }
                }
                iter.next();
            }
            newcones.push(SupportedConeT::NonnegativeConeT(total_dim));
        }

        while let Some(cone) = iter.next() {
            if cone.nvars() != 0 {
                match cone {
                    // collapsible cones.   These are cones that can serve
                    // as the first term in a sequence of cones to be collapsed
                    // into a single nonnegative cone.
                    SupportedConeT::NonnegativeConeT(dim) => {
                        collapse(&mut iter, &mut newcones, *dim)
                    }
                    SupportedConeT::SecondOrderConeT(dim) if *dim == 1 => {
                        collapse(&mut iter, &mut newcones, *dim)
                    }

                    // everything else
                    _ => newcones.push(cone.clone()),
                }
            }
        }
        newcones.shrink_to_fit();
        newcones
    }
}

// -------------------------------------
// Here we make a corresponding internal SupportedCone type that
// dispatches statically against all of our internal cone types
// -------------------------------------

#[allow(clippy::enum_variant_names)]
pub enum SupportedCone {
    ZeroCone(ZeroCone),
    NonnegativeCone(NonnegativeCone),
    SecondOrderCone(SecondOrderCone),
}

// KNP-1 (patch 0007): hand-written static dispatch; upstream used enum_dispatch.
impl Cone for SupportedCone {
    fn degree(&self) -> usize {
        match self {
            SupportedCone::ZeroCone(c) => c.degree(),
            SupportedCone::NonnegativeCone(c) => c.degree(),
            SupportedCone::SecondOrderCone(c) => c.degree(),
        }
    }
    fn numel(&self) -> usize {
        match self {
            SupportedCone::ZeroCone(c) => c.numel(),
            SupportedCone::NonnegativeCone(c) => c.numel(),
            SupportedCone::SecondOrderCone(c) => c.numel(),
        }
    }
    fn is_sparse_expandable(&self) -> bool {
        match self {
            SupportedCone::ZeroCone(c) => c.is_sparse_expandable(),
            SupportedCone::NonnegativeCone(c) => c.is_sparse_expandable(),
            SupportedCone::SecondOrderCone(c) => c.is_sparse_expandable(),
        }
    }
    fn is_symmetric(&self) -> bool {
        match self {
            SupportedCone::ZeroCone(c) => c.is_symmetric(),
            SupportedCone::NonnegativeCone(c) => c.is_symmetric(),
            SupportedCone::SecondOrderCone(c) => c.is_symmetric(),
        }
    }
    fn allows_primal_dual_scaling(&self) -> bool {
        match self {
            SupportedCone::ZeroCone(c) => c.allows_primal_dual_scaling(),
            SupportedCone::NonnegativeCone(c) => c.allows_primal_dual_scaling(),
            SupportedCone::SecondOrderCone(c) => c.allows_primal_dual_scaling(),
        }
    }
    fn rectify_equilibration(&self, delta: &mut [T], e: &[T]) -> bool {
        match self {
            SupportedCone::ZeroCone(c) => c.rectify_equilibration(delta, e),
            SupportedCone::NonnegativeCone(c) => c.rectify_equilibration(delta, e),
            SupportedCone::SecondOrderCone(c) => c.rectify_equilibration(delta, e),
        }
    }
    fn margins(&mut self, z: &mut [T], pd: PrimalOrDualCone) -> (T, T) {
        match self {
            SupportedCone::ZeroCone(c) => c.margins(z, pd),
            SupportedCone::NonnegativeCone(c) => c.margins(z, pd),
            SupportedCone::SecondOrderCone(c) => c.margins(z, pd),
        }
    }
    fn scaled_unit_shift(&self, z: &mut [T], alpha: T, pd: PrimalOrDualCone) {
        match self {
            SupportedCone::ZeroCone(c) => c.scaled_unit_shift(z, alpha, pd),
            SupportedCone::NonnegativeCone(c) => c.scaled_unit_shift(z, alpha, pd),
            SupportedCone::SecondOrderCone(c) => c.scaled_unit_shift(z, alpha, pd),
        }
    }
    fn unit_initialization(&self, z: &mut [T], s: &mut [T]) {
        match self {
            SupportedCone::ZeroCone(c) => c.unit_initialization(z, s),
            SupportedCone::NonnegativeCone(c) => c.unit_initialization(z, s),
            SupportedCone::SecondOrderCone(c) => c.unit_initialization(z, s),
        }
    }
    fn set_identity_scaling(&mut self) {
        match self {
            SupportedCone::ZeroCone(c) => c.set_identity_scaling(),
            SupportedCone::NonnegativeCone(c) => c.set_identity_scaling(),
            SupportedCone::SecondOrderCone(c) => c.set_identity_scaling(),
        }
    }
    fn update_scaling(
        &mut self,
        s: &[T],
        z: &[T],
        mu: T,
        scaling_strategy: ScalingStrategy,
    ) -> bool {
        match self {
            SupportedCone::ZeroCone(c) => c.update_scaling(s, z, mu, scaling_strategy),
            SupportedCone::NonnegativeCone(c) => c.update_scaling(s, z, mu, scaling_strategy),
            SupportedCone::SecondOrderCone(c) => c.update_scaling(s, z, mu, scaling_strategy),
        }
    }
    fn Hs_is_diagonal(&self) -> bool {
        match self {
            SupportedCone::ZeroCone(c) => c.Hs_is_diagonal(),
            SupportedCone::NonnegativeCone(c) => c.Hs_is_diagonal(),
            SupportedCone::SecondOrderCone(c) => c.Hs_is_diagonal(),
        }
    }
    fn get_Hs(&self, Hsblock: &mut [T]) {
        match self {
            SupportedCone::ZeroCone(c) => c.get_Hs(Hsblock),
            SupportedCone::NonnegativeCone(c) => c.get_Hs(Hsblock),
            SupportedCone::SecondOrderCone(c) => c.get_Hs(Hsblock),
        }
    }
    fn mul_Hs(&mut self, y: &mut [T], x: &[T], work: &mut [T]) {
        match self {
            SupportedCone::ZeroCone(c) => c.mul_Hs(y, x, work),
            SupportedCone::NonnegativeCone(c) => c.mul_Hs(y, x, work),
            SupportedCone::SecondOrderCone(c) => c.mul_Hs(y, x, work),
        }
    }
    fn affine_ds(&self, ds: &mut [T], s: &[T]) {
        match self {
            SupportedCone::ZeroCone(c) => c.affine_ds(ds, s),
            SupportedCone::NonnegativeCone(c) => c.affine_ds(ds, s),
            SupportedCone::SecondOrderCone(c) => c.affine_ds(ds, s),
        }
    }
    fn combined_ds_shift(
        &mut self,
        shift: &mut [T],
        step_z: &mut [T],
        step_s: &mut [T],
        sigmamu: T,
    ) {
        match self {
            SupportedCone::ZeroCone(c) => c.combined_ds_shift(shift, step_z, step_s, sigmamu),
            SupportedCone::NonnegativeCone(c) => {
                c.combined_ds_shift(shift, step_z, step_s, sigmamu)
            }
            SupportedCone::SecondOrderCone(c) => {
                c.combined_ds_shift(shift, step_z, step_s, sigmamu)
            }
        }
    }
    fn Ds_from_Dz_offset(&mut self, out: &mut [T], ds: &[T], work: &mut [T], z: &[T]) {
        match self {
            SupportedCone::ZeroCone(c) => c.Ds_from_Dz_offset(out, ds, work, z),
            SupportedCone::NonnegativeCone(c) => c.Ds_from_Dz_offset(out, ds, work, z),
            SupportedCone::SecondOrderCone(c) => c.Ds_from_Dz_offset(out, ds, work, z),
        }
    }
    fn step_length(
        &mut self,
        dz: &[T],
        ds: &[T],
        z: &[T],
        s: &[T],
        settings: &CoreSettings,
        alphamax: T,
    ) -> (T, T) {
        match self {
            SupportedCone::ZeroCone(c) => c.step_length(dz, ds, z, s, settings, alphamax),
            SupportedCone::NonnegativeCone(c) => c.step_length(dz, ds, z, s, settings, alphamax),
            SupportedCone::SecondOrderCone(c) => c.step_length(dz, ds, z, s, settings, alphamax),
        }
    }
    fn compute_barrier(&mut self, z: &[T], s: &[T], dz: &[T], ds: &[T], alpha: T) -> T {
        match self {
            SupportedCone::ZeroCone(c) => c.compute_barrier(z, s, dz, ds, alpha),
            SupportedCone::NonnegativeCone(c) => c.compute_barrier(z, s, dz, ds, alpha),
            SupportedCone::SecondOrderCone(c) => c.compute_barrier(z, s, dz, ds, alpha),
        }
    }
}

impl From<ZeroCone> for SupportedCone {
    fn from(c: ZeroCone) -> Self {
        SupportedCone::ZeroCone(c)
    }
}

impl From<NonnegativeCone> for SupportedCone {
    fn from(c: NonnegativeCone) -> Self {
        SupportedCone::NonnegativeCone(c)
    }
}

impl From<SecondOrderCone> for SupportedCone {
    fn from(c: SecondOrderCone) -> Self {
        SupportedCone::SecondOrderCone(c)
    }
}

// -------------------------------------
// we need a tagging enum with no data fields to act
// as a bridge between the SupportedConeT API types and the
// internal SupportedCone dispatch wrapper.   This enum
// has no data attached at all, so we can just convert to a u8.
// This would not be necessary if I could assign matching
// discriminants to both types, but that feature is not yet
// stable.  See:
// https://rust-lang.github.io/rfcs/2363-arbitrary-enum-discriminant.html
// -------------------------------------

#[allow(clippy::enum_variant_names)]
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash)]
#[repr(u8)]
pub(crate) enum SupportedConeTag {
    ZeroCone = 0,
    NonnegativeCone,
    SecondOrderCone,
}

pub(crate) trait SupportedConeAsTag {
    fn as_tag(&self) -> SupportedConeTag;
}

// user facing API type.   Just gives dimensions / exponents
impl SupportedConeAsTag for SupportedConeT {
    fn as_tag(&self) -> SupportedConeTag {
        match self {
            SupportedConeT::NonnegativeConeT(_) => SupportedConeTag::NonnegativeCone,
            SupportedConeT::ZeroConeT(_) => SupportedConeTag::ZeroCone,
            SupportedConeT::SecondOrderConeT(_) => SupportedConeTag::SecondOrderCone,
        }
    }
}

// internal dispatch container.   Each of the (_) contains the cone data objects
impl SupportedConeAsTag for SupportedCone {
    fn as_tag(&self) -> SupportedConeTag {
        match self {
            SupportedCone::NonnegativeCone(_) => SupportedConeTag::NonnegativeCone,
            SupportedCone::ZeroCone(_) => SupportedConeTag::ZeroCone,
            SupportedCone::SecondOrderCone(_) => SupportedConeTag::SecondOrderCone,
        }
    }
}

/// Returns the name of the cone from its tag.  Used for printing progress.
impl SupportedConeTag {
    pub fn as_str(&self) -> &'static str {
        match self {
            SupportedConeTag::ZeroCone => "ZeroCone",
            SupportedConeTag::NonnegativeCone => "NonnegativeCone",
            SupportedConeTag::SecondOrderCone => "SecondOrderCone",
        }
    }
}

// ----------------------------------------------
// Iterator for the range of indices of the cone

//PJG: type names are not satisfactory.   Try to combine
//with the internal cone generators.

#[allow(dead_code)]
pub(crate) struct RangeSupportedConesIterator<'a> {
    cones: &'a [SupportedConeT],
    index: usize,
    start: usize,
}

#[allow(dead_code)]
impl Iterator for RangeSupportedConesIterator<'_> {
    type Item = std::ops::Range<usize>;

    fn next(&mut self) -> Option<Self::Item> {
        if self.index < self.cones.len() {
            let cone = &self.cones[self.index];
            let stop = self.start + cone.nvars();
            let range = self.start..stop;
            self.index += 1;
            self.start = stop;
            Some(range)
        } else {
            None
        }
    }
}
#[allow(dead_code)]
pub(crate) trait ConeRanges<'a> {
    fn rng_cones_iter(&'a self) -> RangeSupportedConesIterator<'a>;
}

#[allow(dead_code)]
impl<'a> ConeRanges<'a> for [SupportedConeT] {
    fn rng_cones_iter(&'a self) -> RangeSupportedConesIterator<'a> {
        RangeSupportedConesIterator::<'a> {
            cones: self,
            index: 0,
            start: 0,
        }
    }
}
